 "content": "def transform(grid):
    """Project the three-cell horizontal color bar toward its matching markers."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # Locate the contiguous three-color bar, which is on the same row.
    bar = None
    for r, row in enumerate(grid):
        for c in range(w - 2):
            if row[c] and row[c + 1] and row[c + 2]:
                bar = (r, c, row[c], row[c + 1], row[c + 2])
                break
        if bar:
            break
    if bar is None:
        return out

    r0, c0, left_color, middle_color, right_color = bar
    # The center bar color continues vertically through the full grid.
    for r in range(r0, h):
        out[r][c0 + 1] = middle_color

    # Each end color connects its bar cell vertically to the matching lone
    # marker, then horizontally from the bar column to that marker's edge.
    for color, c in ((left_color, c0), (right_color, c0 + 2)):
        markers = [(r, x) for r in range(h) for x in range(w)
                   if grid[r][x] == color and not (r == r0 and c <= x <= c + 2)]
        if not markers:
            continue
        # The intended marker is the external occurrence of this end color.
        mr, mc = markers[0]
        for r in range(min(r0, mr), max(r0, mr) + 1):
            out[r][c] = color
        for x in range(min(c, mc), max(c, mc) + 1):
            out[mr][x] = color
    return out


